// Extract job and candidates from webhook body
const body = $input.first().json.body || $input.first().json;

const job = body.job;
const candidates = body.candidates || [];

if (!job || !candidates.length) {
  return [{ json: { error: 'Missing job or candidates data' } }];
}

// Build a compact prompt for Gemini
const jobSummary = `
Job Title: ${job.title}
Description: ${(job.description || '').slice(0, 500)}
Required Skills: ${(job.skills_required || []).join(', ')}
Job Type: ${job.job_type || 'N/A'}
Location: ${job.location || 'N/A'}
Salary: ${job.salary_range || 'N/A'}
Min Experience: ${job.experience_min || 'N/A'} years
Nationality Required: ${job.nationality_required || 'All'}
`.trim();

const candidateList = candidates.map((c, i) => `
[Candidate ${i + 1}] ID: ${c.id}
Name: ${c.name}
Headline: ${c.headline || 'N/A'}
Skills: ${(c.skills || []).join(', ')}
Experience: ${c.years_experience || 0} years
Location: ${c.location || 'N/A'}
Nationality: ${c.nationality || 'N/A'}
Education: ${(c.education || []).join(', ') || 'N/A'}
Summary: ${(c.summary || '').slice(0, 200)}
`.trim()).join('\n---\n');

const prompt = `You are an expert HR AI recruiter for the UAE market. Analyze the following job posting and rank the candidates by their suitability.

IMPORTANT RULES:
1. Consider SEMANTIC similarity of skills (e.g., "React" relates to "Frontend", "Node.js" relates to "Backend")
2. Consider transferable skills and industry experience
3. Match education level to job requirements  
4. Consider nationality preferences if specified
5. Consider location proximity
6. Give HIGHER weight to exact skill matches, but also credit related/transferable skills
7. Respond ONLY with valid JSON

=== JOB POSTING ===
${jobSummary}

=== CANDIDATES ===
${candidateList}

=== OUTPUT FORMAT ===
Return ONLY a JSON object (no markdown, no backticks) with this exact structure:
{
  "rankings": [
    {
      "candidate_id": "uuid",
      "name": "string",
      "score": 0-100,
      "reasoning": "Arabic explanation why this candidate matches or doesn't (2-3 sentences)",
      "strengths": ["skill1", "skill2"],
      "gaps": ["missing_skill1"],
      "recommendation": "مناسب جداً" | "مناسب" | "مناسب جزئياً" | "غير مناسب"
    }
  ]
}

Rank from highest score to lowest. Be fair and analytical.`;

return [{ json: { prompt, job_id: job.id, employer_id: body.employer_id, candidate_count: candidates.length } }];

// Parse Gemini response and clean it up
const rawText = $input.first().json.text || $input.first().json.response || '';

// Try to extract JSON from the response
let result;
try {
  // Remove markdown code fences if present
  let cleaned = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  result = JSON.parse(cleaned);
} catch (e) {
  // If JSON parse fails, try to find JSON in the text
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      result = JSON.parse(jsonMatch[0]);
    } catch (e2) {
      result = {
        rankings: [],
        error: 'Failed to parse AI response',
        raw: rawText.slice(0, 500)
      };
    }
  } else {
    result = {
      rankings: [],
      error: 'No JSON found in AI response',
      raw: rawText.slice(0, 500)
    };
  }
}

// Ensure rankings exist and are sorted
if (result.rankings && Array.isArray(result.rankings)) {
  result.rankings.sort((a, b) => (b.score || 0) - (a.score || 0));
}

return [{ json: result }];
